SourceCode.Declaration:
/// <summary>
///     The <c>AVABPInfoUIBuilder</c> class is the UI builder class for <c>BP-Info</c>
/// </summary>
class AVABPInfoUIBuilder extends SysOperationAutomaticUIBuilder
{
    AVABPInfoContract   contract;

    DialogField df_AVABPInfoNewBuildingProjects;
    DialogField df_AVABPInfoNewRequests;
    //DialogField df_AVABPInfoNewRequestsRICO;
    DialogField df_AVABPInfoNewQuotations;
    DialogField df_AVABPInfoChangedQuotations;
    DialogField df_AVABPInfoChangedBuildingProjects;
    DialogField df_AVABPInfoNewChangedActivities;

    DialogField df_AVABPInfoBuildNewData;
    DialogField df_AVABPInfoDateTime;
    DialogField df_AVABPInfoFromKCS_KBVBuildingProjectID;

    DialogField df_AVABPInfoSendInfo;
    DialogField df_AVABPInfoTestEmailTo;
    DialogField df_AVABPInfoHCMWorkerRecId;

}

Method.Source:
/// <summary>
///    AVA <c>getContract</c> method.
/// </summary>
/// <returns>
///    <c>AVABPInfoContract</c> as return value
/// </returns>
private AVABPInfoContract getContract()
{
    if(!contract)
    {
        contract = this.dataContractObject() as AVABPInfoContract;
    }

    return contract;
}

/// <summary>
///    AVA <c>getFromDialog</c> method.
/// </summary>
public void getFromDialog()
{
    super();

    this.getContract().parmFromKCS_KBVBuildingProjectID(df_AVABPInfoFromKCS_KBVBuildingProjectID.value());
    this.getContract().parmIncludeNewRequests(df_AVABPInfoNewRequests.value());
    //this.getContract().parmIncludeNewRequestsRICO(df_AVABPInfoNewRequestsRICO.value());
}

/// <summary>
///    AVA <c>postBuild</c> method.
/// </summary>
public void postBuild()
{
    super();

    // get references to dialog controls after creation
    df_AVABPInfoNewBuildingProjects             = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmIncludeNewBuildingProjects));
    df_AVABPInfoNewRequests                     = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmIncludeNewRequests));
    /*
    df_AVABPInfoNewRequestsRICO                 = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmIncludeNewRequestsRICO));
    */
    df_AVABPInfoNewQuotations                   = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmIncludeNewQuotations));
    df_AVABPInfoChangedQuotations               = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmIncludeChangedQuotations));
    df_AVABPInfoChangedBuildingProjects         = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmIncludeChangedBuildingProjects));
    df_AVABPInfoNewChangedActivities            = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmNewChangedActivities));

    df_AVABPInfoBuildNewData                    = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmRebuildData));
    df_AVABPInfoDateTime                        = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmStartDateTime));
    df_AVABPInfoFromKCS_KBVBuildingProjectID    = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmFromKCS_KBVBuildingProjectID));
    df_AVABPInfoHCMWorkerRecId                  = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmHCMWorker));

    df_AVABPInfoSendInfo                        = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmSendInfo));
    df_AVABPInfoTestEmailTo                     = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                                    methodStr(AVABPInfoContract, parmTestEmailTo));

    df_AVABPInfoFromKCS_KBVBuildingProjectID.enabled(df_AVABPInfoFromKCS_KBVBuildingProjectID.value() == '');
}

/// <summary>
///    AVA <c>postRun</c> method.
/// </summary>
public void postRun()
{
    super();

    //modified
    df_AVABPInfoSendInfo.registerOverrideMethod(                        methodStr(FormStringControl, modified),
                                                                        methodStr(AVABPInfoUIBuilder, modifiedSendInfo),
                                                                        this);
    df_AVABPInfoTestEmailTo.registerOverrideMethod(                     methodstr(FormCheckBoxControl, modified),
                                                                        methodstr(AVABPInfoUIBuilder, modifiedTestEmailTo),
                                                                        this);
    df_AVABPInfoFromKCS_KBVBuildingProjectID.registerOverrideMethod(    methodstr(FormCheckBoxControl, modified),
                                                                        methodstr(AVABPInfoUIBuilder, modifiedFromKCS_KBVBuildingProjectID),
                                                                        this);
}

/// <summary>
///    AVA <c>modifiedSendInfo</c> method.
/// </summary>
/// <param name="_df_AVABPInfoSendInfo">
///    <c>FormCheckBoxControl</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean modifiedSendInfo(FormCheckBoxControl _df_AVABPInfoSendInfo)
{
    if(_df_AVABPInfoSendInfo.value() == NoYes::Yes)
    {
        df_AVABPInfoTestEmailTo.value(KCS_KBVParameters::find().BVInfoTestEmail);
    }
    else
    {
        df_AVABPInfoTestEmailTo.value('');
    }
    return true;
}

/// <summary>
///    AVA <c>modifiedTestEmailTo</c> method.
/// </summary>
/// <param name="_df_AVABPInfoTestEmailTo">
///    <c>FormStringControl</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean modifiedTestEmailTo(FormStringControl _df_AVABPInfoTestEmailTo)
{
    if(_df_AVABPInfoTestEmailTo.valueStr() == '')
    {
        df_AVABPInfoSendInfo.value(NoYes::No);
    }
    return true;
}

/// <summary>
///    AVA <c>modifiedFromKCS_KBVBuildingProjectID</c> method.
/// </summary>
/// <param name="_df_AVABPInfoFromKCS_KBVBuildingProjectID">
///    <c>FormStringControl</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean modifiedFromKCS_KBVBuildingProjectID(FormStringControl _df_AVABPInfoFromKCS_KBVBuildingProjectID)
{
    if(_df_AVABPInfoFromKCS_KBVBuildingProjectID.valueStr())
    {
        if(!KCS_KBVBuildingProjectTable::find(_df_AVABPInfoFromKCS_KBVBuildingProjectID.valueStr()).RecId)
        {
            df_AVABPInfoFromKCS_KBVBuildingProjectID.value('');
        }
    }
    return true;
}
